CREATE TABLE IF NOT EXISTS message_templates (id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id),name TEXT NOT NULL,channel TEXT NOT NULL,language TEXT NOT NULL,template_type TEXT NOT NULL,status TEXT NOT NULL,current_version_id TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_message_templates_event_status ON message_templates(event_id,status);
CREATE TABLE IF NOT EXISTS message_template_versions (id TEXT PRIMARY KEY,template_id TEXT NOT NULL REFERENCES message_templates(id),version_no INTEGER NOT NULL,subject TEXT NOT NULL,content TEXT NOT NULL,variables_json TEXT NOT NULL,review_status TEXT NOT NULL,submitted_by TEXT NOT NULL,approved_by TEXT,published_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS uidx_message_template_version ON message_template_versions(template_id,version_no);
CREATE TABLE IF NOT EXISTS message_tasks (id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id),name TEXT NOT NULL,task_type TEXT NOT NULL,channel TEXT NOT NULL,template_version_id TEXT NOT NULL REFERENCES message_template_versions(id),recipient_source TEXT NOT NULL,filter_snapshot_json TEXT NOT NULL,recipient_count INTEGER NOT NULL,dedup_count INTEGER NOT NULL,unsubscribe_count INTEGER NOT NULL,invalid_count INTEGER NOT NULL,status TEXT NOT NULL,creator_name TEXT NOT NULL,reviewer_name TEXT,schedule_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_message_tasks_event_status ON message_tasks(event_id,status);
CREATE TABLE IF NOT EXISTS message_recipient_snapshots (id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES message_tasks(id),source TEXT NOT NULL,source_ref TEXT,display_name TEXT NOT NULL,contact TEXT NOT NULL,consent_status TEXT NOT NULL,variables_json TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_message_recipients_task_status ON message_recipient_snapshots(task_id,status);
CREATE TABLE IF NOT EXISTS message_deliveries (id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES message_tasks(id),recipient_id TEXT NOT NULL REFERENCES message_recipient_snapshots(id),provider TEXT NOT NULL,provider_request_id TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL,reason TEXT,occurred_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS uidx_message_delivery_task_recipient ON message_deliveries(task_id,recipient_id);
CREATE TABLE IF NOT EXISTS unsubscribe_records (id TEXT PRIMARY KEY,event_id TEXT REFERENCES events(id),identity TEXT NOT NULL,channel TEXT NOT NULL,scope TEXT NOT NULL,source TEXT NOT NULL,occurred_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS uidx_unsubscribe_identity_scope ON unsubscribe_records(identity,channel,scope);
